 const baselineInviteChance=Math.max(18,Math.min(92,Math.round(50+(s.network.companyReputation-avgQuality)*.7+(avgPrice-s.network.companyPriceIndex)*35-capacityPenalty))),campaign=s.network.marketingCampaign;
 const inviteChance=Math.max(18,Math.min(96,baselineInviteChance+(campaign?.inviteBonus||0)));
