 // Four seasonal rotations only schedule leave; actual usage is recorded on its date.
 if(date.endsWith('-01-01')){for(const e of s.employees){e.vacationDaysUsed=0;e.vacationDaysTaken=[];e.vacationPlan=[];}s.annualStats.vacationDays=0;scheduleVacation(s,1);}
